#include <bits/stdc++.h>
using namespace std;
using ll=long long;

int main() {
	ll t;
	cin>>t;
	
	while(t--){
	      ll n;
	      cin>>n;
	      
	      vector<ll>v(3*n);
	      for(ll i=0;i<3*n;i++) cin>>v[i];
	      
	      sort(v.rbegin(),v.rend());
	      
	      vector<ll>pre(3*n+1,0);
	      
	      for(ll i=1;i<=3*n;i++){
	           pre[i]=pre[i-1]+v[i-1];
	      }
	      
	      ll ansi=0;
	      
	      for(int z=0;z<=2*n;z++){
	           ll l=max(0LL,z-n);
	           ll r=z/2;
	           
	           
	           while(l<r){
	                   ll mid=l+(r-l)/2;
	                   
	                   ll q1=2*z-3*mid;
	                   ll q2=2*z-3*(mid+1);
	                   
	                   ll v1=2*pre[mid]+pre[q1]+3*pre[3*n-z];
	                   
	                   ll v2=2*pre[mid+1]+pre[q2]+3*pre[3*n-z];
	                   
	                   if(v1<=v2) l=mid+1;
	                   else r=mid;
	               
	           }
	           
	           ll q=2*z-3*l;
	           
	           ll val=2*pre[l]+pre[q]+3*pre[3*n-z];
	           ansi=max(ansi,val);
	      }
	      
	    cout<<ansi<<endl;
	}
}
